function leaveBluetoothLobby(): void {
  if (bluetooth?.everConnected) {
    showDialog(
      "断开蓝牙对局",
      "确定要断开当前蓝牙对局并返回主菜单吗？",
      "确认断开",
      () => {
        nativeBluetooth()?.disconnect();
        bluetooth = undefined;
        showMainMenu();
      },
    );
    return;
  }
  nativeBluetooth()?.disconnect();
  bluetooth = undefined;
  showMainMenu();
}

